from eth_utils import to_checksum_address

TAKING_AMOUNT_DATA = 3  # enum index


def parse_extension_full(extension_hex: str):
    data = bytes.fromhex(extension_hex.removeprefix("0x"))

    # -------------------------
    # 1. split offsets + concat
    # -------------------------
    offsets_raw = data[:32]
    concat = data[32:]

    offsets = [
        int.from_bytes(offsets_raw[i:i+4], "big")
        for i in range(0, 32, 4)
    ]

    # -------------------------
    # 2. TakingAmountData slice
    # -------------------------
    start = offsets[TAKING_AMOUNT_DATA]

    candidates = [
        offsets[i]
        for i in range(len(offsets))
        if offsets[i] > start and i != TAKING_AMOUNT_DATA
    ]

    end = min(candidates) if candidates else len(concat)

    taking_amount_data = concat[start:end]

    if len(taking_amount_data) < 20:
        raise ValueError("TakingAmountData too short")

    # -------------------------
    # 3. split address + tail
    # -------------------------
    target_address_bytes = taking_amount_data[:20]
    tail = taking_amount_data[20:]

    target_address = to_checksum_address(target_address_bytes.hex())

    # -------------------------
    # 4. whitelist parsing (FIXED)
    # -------------------------
    if len(tail) < 1:
        finalized_taking_amount_data = b""
    else:
        size = int(tail[0])

        whitelist_end = 1 + 10 * size

        # sanity check (ВАЖНО)
        if whitelist_end > len(tail):
            raise ValueError(
                f"Whitelist overflow: size={size}, "
                f"expected_end={whitelist_end}, tail_len={len(tail)}"
            )

        # Solidity-equivalent:
        # tail = whitelistData[1 + 10 * size:]
        finalized_taking_amount_data = tail[whitelist_end:]

    # -------------------------
    # 5. result
    # -------------------------
    return {
        "offsets": offsets,
        "taking_amount_data_hex": taking_amount_data.hex(),
        "target_address": target_address,
        "target_address_raw": target_address_bytes.hex(),
        "tail_hex": tail.hex(),
        "finalized_taking_amount_data_hex": finalized_taking_amount_data.hex(),
    }


# -------------------------
# example usage
# -------------------------
if __name__ == "__main__":
    extension = ""

    result = parse_extension_full(extension)

    for k, v in result.items():
        print(k, ":", v)




